// Some portions generated by Codex
package org.eclipse.rdf4j.sail.memory;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNull;

import java.util.List;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.memory.model.MemValueFactory;
import org.junit.jupiter.api.Test;

class MemoryAbsentBlankNodeReferenceTest {

	@Test
	void preparingAndEvaluatingAbsentReferencesLeavesStatementsUnchanged() throws Exception {
		var repository = new SailRepository(new MemoryStore());
		repository.init();
		try {
			try (var connection = repository.getConnection()) {
				var vf = SimpleValueFactory.getInstance();
				var absent = vf.createBNode("absent-reference");
				connection.add(vf.createIRI("urn:s"), vf.createIRI("urn:p"), vf.createLiteral("existing"));

				var values = connection
						.prepareTupleQuery("SELECT ?node WHERE { VALUES ?node { <_:absent-reference> } }");

				try (var rows = values.evaluate()) {
					assertEquals(absent, rows.next().getValue("node"));
					assertFalse(rows.hasNext());
				}

				var expression = connection.prepareTupleQuery("SELECT (<_:absent-reference> AS ?node) WHERE {}");

				try (var rows = expression.evaluate()) {
					assertEquals(absent, rows.next().getValue("node"));
					assertFalse(rows.hasNext());
				}

				var ask = connection.prepareBooleanQuery("ASK { <_:absent-reference> ?p ?o }");

				assertFalse(ask.evaluate());

				assertEquals(1, connection.size());
				try (var statements = connection.getStatements(null, null, null, false)) {
					var statement = statements.next();
					assertEquals(vf.createIRI("urn:s"), statement.getSubject());
					assertEquals(vf.createIRI("urn:p"), statement.getPredicate());
					assertEquals(vf.createLiteral("existing"), statement.getObject());
					assertFalse(statements.hasNext());
				}
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void deletingAbsentDirectAndNestedReferencesDoesNotMaterializeValues() {
		var repository = new SailRepository(new MemoryStore());
		repository.init();
		try (var connection = repository.getConnection()) {
			var memoryValueFactory = (MemValueFactory) repository.getValueFactory();
			var valueFactory = SimpleValueFactory.getInstance();
			List<String> identifiers = List.of("absent-delete-subject", "absent-delete-object", "absent-delete-graph",
					"absent-delete-nested-subject", "absent-delete-nested-object");
			var nested = valueFactory.createTripleTerm(valueFactory.createBNode(identifiers.get(3)),
					valueFactory.createIRI("urn:q"), valueFactory.createBNode(identifiers.get(4)));
			assertNull(memoryValueFactory.getMemValue(nested));
			identifiers.forEach(id -> assertNull(memoryValueFactory.getMemBNode(valueFactory.createBNode(id))));

			connection.prepareUpdate("DELETE DATA { <_:absent-delete-subject> <urn:p> <_:absent-delete-object> . "
					+ "GRAPH <_:absent-delete-graph> { <urn:s> <urn:p> <<(<_:absent-delete-nested-subject> "
					+ "<urn:q> <_:absent-delete-nested-object>)>> . } }").execute();

			assertEquals(0, connection.size());
			identifiers.forEach(id -> assertNull(memoryValueFactory.getMemBNode(valueFactory.createBNode(id))));
			assertNull(memoryValueFactory.getMemValue(nested));
		} finally {
			repository.shutDown();
		}
	}
}
